nav.innerHTML=`<a href="#inicio">Inicio</a><div class="nav-services"><button id="services-toggle" aria-expanded="false" aria-controls="services-menu">Servicios <span>⌄</span></button><div id="services-menu" class="services-menu" hidden>${menuOrder.map(id=>`<a href="#${id}">${icon(config[id].icon)}<span>${config[id].name}</span></a>`).join('')}<a class="all-services" href="#servicios">Ver todos los servicios ${icon('arrow')}</a></div></div><a href="#portafolio">Portafolio</a><a href="#cursos">Cursos</a><a href="#sobre-mi">Sobre mí</a><a href="#contacto">Contacto</a><a class="mobile-quote button" href="${wa('Hola JC Creativo, me interesa cotizar un proyecto.')}">Cotizar ${icon('arrow')}</a>`;
const menuButton=$('#menuButton'),submenu=$('#services-menu'),servicesToggle=$('#services-toggle'),mobile=matchMedia('(max-width: 900px)');
function closeSub(){submenu.hidden=true;servicesToggle.setAttribute('aria-expanded','false')}
function closeMenu(focus=false){nav.classList.remove('open');menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Abrir menú');document.body.classList.remove('menu-open');nav.inert=mobile.matches;closeSub();if(focus)menuButton.focus()}
function syncMenu(){nav.inert=mobile.matches&&!nav.classList.contains('open');if(!mobile.matches)closeMenu()}
menuButton.onclick=()=>{if(nav.classList.contains('open'))return closeMenu(true);nav.inert=false;nav.classList.add('open');document.body.classList.add('menu-open');menuButton.setAttribute('aria-expanded','true');menuButton.setAttribute('aria-label','Cerrar menú');$('a',nav).focus()};
servicesToggle.onclick=()=>{submenu.hidden=!submenu.hidden;servicesToggle.setAttribute('aria-expanded',String(!submenu.hidden))};
document.addEventListener('click',e=>{if(!e.target.closest('.nav-services'))closeSub();if(mobile.matches&&nav.classList.contains('open')&&!e.target.closest('#header'))closeMenu()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(nav.classList.contains('open'))closeMenu(true);else if(!submenu.hidden){closeSub();servicesToggle.focus()}}if(e.key==='Tab'&&mobile.matches&&nav.classList.contains('open')){const focusable=$$('a,button',nav).filter(n=>!n.closest('[hidden]'));focusable.push(menuButton);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
