function filterPortfolio(){let count=0,total=0;$$('.project-card',portfolio).forEach(card=>{const matches=filter==='all'||card.dataset.categories.split(' ').includes(filter);if(matches)total++;card.hidden=!matches||(!showAll&&count>=6);if(matches)count++});$('#more-projects').hidden=showAll||total<=6;$('#portfolio-status').textContent=`${Math.min(showAll?total:6,total)} de ${total} proyectos`;$$('[data-portfolio-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.portfolioFilter===filter)))}
